import { z } from 'zod';

export const wards = [
  ['141011', 'tsurumi', '鶴見区'],
  ['141020', 'kanagawa', '神奈川区'],
  ['141038', 'nishi', '西区'],
  ['141046', 'naka', '中区'],
  ['141054', 'minami', '南区'],
  ['141119', 'konan', '港南区'],
  ['141062', 'hodogaya', '保土ケ谷区'],
  ['141127', 'asahi', '旭区'],
  ['141071', 'isogo', '磯子区'],
  ['141089', 'kanazawa', '金沢区'],
  ['141097', 'kohoku', '港北区'],
  ['141135', 'midori', '緑区'],
  ['141178', 'aoba', '青葉区'],
  ['141186', 'tsuzuki', '都筑区'],
  ['141101', 'totsuka', '戸塚区'],
  ['141151', 'sakae', '栄区'],
  ['141160', 'izumi', '泉区'],
  ['141143', 'seya', '瀬谷区'],
].map(([code, slug, name]) => ({ code, slug, name }));
export const geographies = [{ code: '141003', slug: 'yokohama', name: '横浜市' }, ...wards];
export const metrics = [
  {
    id: 'population',
    name: '人口',
    unit: '人',
    column: '人口総数［人］',
    definition:
      '国勢調査を基礎に出生・死亡・転出入等を加減した推計人口。住民基本台帳の登録者数とは異なる。',
    additive: true,
  },
  {
    id: 'households',
    name: '世帯数',
    unit: '世帯',
    column: '世帯数［世帯］',
    definition: '推計人口調査における世帯数。世帯の人数や家族構成は示さない。',
    additive: true,
  },
  {
    id: 'male',
    name: '男性人口',
    unit: '人',
    column: '男［人］',
    definition: '推計人口調査の男性人口。',
    additive: true,
  },
  {
    id: 'female',
    name: '女性人口',
    unit: '人',
    column: '女［人］',
    definition: '推計人口調査の女性人口。',
    additive: true,
  },
  {
    id: 'area',
    name: '面積',
    unit: 'km²',
    column: '面積［平方キロメートル］',
    definition: '原典に掲載された市区の面積。丸めと計測時点に注意。',
    additive: false,
  },
  {
    id: 'household_size',
    name: '1世帯あたり人数',
    unit: '人/世帯',
    column: '１世帯当たり人員［人］',
    definition:
      '人口を世帯数で割った原典の値。高齢単身世帯や子育て世帯の割合を直接示す指標ではない。',
    additive: false,
  },
  {
    id: 'density',
    name: '人口密度',
    unit: '人/km²',
    column: '人口密度［人／平方キロメートル］',
    definition: '人口を面積で割った原典の値。区内の人口の偏りは示さない。',
    additive: false,
  },
  {
    id: 'household_change',
    name: '届出による世帯増減',
    unit: '世帯',
    column: '届出による前月比増減の世帯数［世帯］',
    definition: '前月の届出による増減。統計基準の修正を含む残高の差とは一致しない場合がある。',
    additive: true,
  },
  {
    id: 'population_change',
    name: '届出による人口増減',
    unit: '人',
    column: '届出による前月比増減の人口［人］',
    definition:
      '前月の届出による増減。出生・死亡・転入・転出の内訳や政策効果はこの値だけでは判断できない。',
    additive: true,
  },
] as const;
export type MetricId = (typeof metrics)[number]['id'];
const date = z.iso.date();
export const snapshotSchema = z
  .object({
    id: z.string().regex(/^[a-f0-9]{64}$/),
    url: z.url(),
    title: z.string().min(1),
    sourcePage: z.url(),
    retrievedAt: z.iso.datetime(),
    publishedAt: date.nullable(),
    sha256: z.string().regex(/^[a-f0-9]{64}$/),
    path: z.string().regex(/^data\/raw\/[a-f0-9]{64}\.csv$/),
    license: z.literal('CC-BY-4.0'),
    publisher: z.literal('横浜市'),
    parserVersion: z.literal('population-csv-v1'),
  })
  .strict();
export const observationSchema = z
  .object({
    id: z.string(),
    geography: z.string(),
    metric: z.enum(metrics.map((m) => m.id)),
    period: date,
    value: z.number().finite(),
    sourceId: z.string(),
    row: z.number().int().min(2),
    column: z.string(),
    revision: z.number().int().positive(),
    status: z.literal('machine_verified'),
  })
  .strict();
export const datasetSchema = z
  .object({
    schemaVersion: z.literal(1),
    generatedAt: z.iso.datetime(),
    snapshots: z.array(snapshotSchema).min(1),
    observations: z.array(observationSchema).min(1),
  })
  .strict();
export type Snapshot = z.infer<typeof snapshotSchema>;
export type Observation = z.infer<typeof observationSchema>;
export type Dataset = z.infer<typeof datasetSchema>;

export function validateDataset(input: unknown): Dataset {
  const data = datasetSchema.parse(input);
  const sources = new Map(data.snapshots.map((s) => [s.id, s]));
  if (sources.size !== data.snapshots.length) throw new Error('Duplicate snapshot');
  const keys = new Set<string>();
  const groups = new Map<string, Observation[]>();
  for (const o of data.observations) {
    if (!sources.has(o.sourceId)) throw new Error(`Missing source: ${o.id}`);
    if (!geographies.some((g) => g.code === o.geography)) throw new Error('Unknown geography');
    const key = `${o.period}:${o.geography}:${o.metric}`;
    if (keys.has(key)) throw new Error(`Duplicate observation: ${key}`);
    keys.add(key);
    if (o.period > data.generatedAt.slice(0, 10)) throw new Error('Future observation');
    if (!['area', 'household_size'].includes(o.metric) && !Number.isInteger(o.value))
      throw new Error('Fractional count');
    if (!o.metric.endsWith('_change') && o.value <= 0)
      throw new Error('Invalid non-positive value');
    const group = groups.get(o.period) ?? [];
    group.push(o);
    groups.set(o.period, group);
  }
  for (const [period, group] of groups) {
    if (group.length !== geographies.length * metrics.length)
      throw new Error(`Incomplete period: ${period}`);
    const get = (code: string, metric: MetricId) => {
      const o = group.find((o) => o.geography === code && o.metric === metric);
      if (!o) throw new Error(`Missing metric: ${period}:${code}:${metric}`);
      return o.value;
    };
    for (const g of geographies) {
      if (get(g.code, 'male') + get(g.code, 'female') !== get(g.code, 'population'))
        throw new Error('Sex total mismatch');
      if (
        Math.abs(
          get(g.code, 'population') / get(g.code, 'households') - get(g.code, 'household_size'),
        ) > 0.011
      )
        throw new Error('Household ratio mismatch');
      if (Math.abs(get(g.code, 'population') / get(g.code, 'area') - get(g.code, 'density')) > 1)
        throw new Error('Density mismatch');
    }
    for (const m of metrics.filter((m) => m.additive)) {
      if (wards.reduce((sum, g) => sum + get(g.code, m.id), 0) !== get('141003', m.id))
        throw new Error(`Ward sum mismatch: ${period}:${m.id}`);
    }
  }
  return data;
}

import { type Dataset, geographies, type MetricId, metrics } from './schema.ts';
export const number = (value: number) =>
  new Intl.NumberFormat('ja-JP', { maximumFractionDigits: 2 }).format(value);
export function series(data: Dataset, geography: string, metric: MetricId) {
  return data.observations
    .filter((o) => o.geography === geography && o.metric === metric)
    .sort((a, b) => a.period.localeCompare(b.period));
}
export function latest(data: Dataset, geography: string, metric: MetricId) {
  const result = series(data, geography, metric).at(-1);
  if (!result) throw new Error('No observation');
  return result;
}
export function compare(data: Dataset, metric: MetricId, period: string) {
  return data.observations
    .filter((o) => o.metric === metric && o.period === period && o.geography !== '141003')
    .sort((a, b) => b.value - a.value);
}
export function fact(data: Dataset, geography: string, metric: MetricId) {
  const observation = latest(data, geography, metric);
  const source = data.snapshots.find((s) => s.id === observation.sourceId);
  const definition = metrics.find((m) => m.id === metric);
  const geo = geographies.find((g) => g.code === geography);
  if (!source || !definition || !geo) throw new Error('Unresolved fact');
  return {
    statement: `${observation.period}時点の${geo.name}の${definition.name}は${number(observation.value)}${definition.unit}。`,
    observation,
    source,
    definition,
  };
}

import {
  geographies,
  metrics,
  type MetricId,
  type Snapshot,
} from "../../../../packages/core/schema";
const payload = document.querySelector("#comparison-data");
const metricSelect = document.querySelector<HTMLSelectElement>("#metric");
const periodSelect = document.querySelector<HTMLSelectElement>("#period");
if (!payload?.textContent || !metricSelect || !periodSelect)
  throw new Error("Missing comparison data");
const {
  compact,
  snapshots,
}: { compact: [string, MetricId, string, number][]; snapshots: Snapshot[] } =
  JSON.parse(payload.textContent);
const metricInput = metricSelect;
const periodInput = periodSelect;
function render() {
  const metric = metrics.find((m) => m.id === metricInput.value);
  const period = periodInput.value;
  if (!metric) return;
  const rows = compact
    .filter((o) => o[1] === metric.id && o[2] === period && o[0] !== "141003")
    .sort((a, b) => b[3] - a[3]);
  const max = Math.max(1, ...rows.map((o) => Math.abs(o[3])));
  const body = document.querySelector("#comparison-body");
  if (!body) return;
  body.replaceChildren();
  for (const row of rows) {
    const ward = geographies.find((w) => w.code === row[0]);
    if (!ward) throw new Error("Unknown ward");
    const tr = document.createElement("tr");
    const name = document.createElement("th");
    name.scope = "row";
    const a = document.createElement("a");
    a.href = `/wards/${ward.slug}/`;
    a.textContent = ward.name;
    name.append(a);
    const value = document.createElement("td");
    value.className = "numeric";
    value.textContent = new Intl.NumberFormat("ja-JP", {
      maximumFractionDigits: 2,
    }).format(row[3]);
    const bar = document.createElement("td");
    const track = document.createElement("span");
    track.className = "bar-track";
    track.setAttribute("aria-hidden", "true");
    const fill = document.createElement("span");
    fill.className = "bar-fill";
    fill.style.width = `${(Math.abs(row[3]) / max) * 100}%`;
    track.append(fill);
    bar.append(track);
    const citation = document.createElement("td");
    const link = document.createElement("a");
    link.className = "cite source-icon";
    link.setAttribute("aria-label", "横浜市の掲載ページを開く");
    link.title = "横浜市の掲載ページを開く";
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    const icon = document.createElement("span");
    icon.setAttribute("aria-hidden", "true");
    link.append(icon);
    const snap = snapshots.find((s) =>
      s.url.endsWith(
        `e1yokohama${period.slice(2, 4)}${period.slice(5, 7)}.csv`,
      ),
    );
    if (!snap) throw new Error("Source missing");
    link.href = snap.sourcePage;
    citation.append(link);
    tr.append(name, value, bar, citation);
    body.append(tr);
  }
  const definition = document.querySelector("#definition");
  const heading = document.querySelector("#value-heading");
  const caption = document.querySelector("#comparison-caption");
  if (definition) definition.textContent = metric.definition;
  if (heading) heading.textContent = `${metric.name}（${metric.unit}）`;
  if (caption)
    caption.textContent = `${period}時点の${metric.name}（${metric.unit}）。値の大きい順。`;
  history.replaceState(
    null,
    "",
    `?${new URLSearchParams({ metric: metric.id, period })}`,
  );
}
const params = new URLSearchParams(location.search);
if (metrics.some((m) => m.id === params.get("metric")))
  metricInput.value = params.get("metric") ?? "population";
if ([...periodInput.options].some((o) => o.value === params.get("period")))
  periodInput.value = params.get("period") ?? periodInput.value;
metricInput.addEventListener("change", render);
periodInput.addEventListener("change", render);
if (location.search) render();

metricInput.disabled = false;
periodInput.disabled = false;

---
import { data, series, number } from "../data";
import type { MetricId } from "../../../../packages/core/schema";
interface Props {
  geography: string;
  metric?: MetricId;
}
const { geography, metric = "population" } = Astro.props;
const points = series(data, geography, metric);
const min = Math.min(...points.map((o) => o.value)),
  max = Math.max(...points.map((o) => o.value));
const spread = max - min || 1;
const coords = points
  .map(
    (o, i) =>
      `${56 + (i / Math.max(1, points.length - 1)) * 560},${170 - ((o.value - min) / spread) * 125}`,
  )
  .join(" ");
---

<figure style="margin:0">
  <svg
    class="chart"
    viewBox="0 0 650 220"
    role="img"
    aria-label={`${points[0].period}から${points.at(-1)?.period}までの推移。最小${number(min)}、最大${number(max)}。詳しい数値は下の表で確認できます。`}
  >
    <path
      d="M56 45H616M56 107H616M56 170H616"
      stroke="var(--line)"
      stroke-dasharray="3 4"></path>
    <polyline
      points={coords}
      stroke="var(--chart)"
      stroke-width="2.5"
      fill="none"></polyline>
    <text x="56" y="24">{number(max)}</text><text x="56" y="192"
      >{number(min)}</text
    >
    <text x="56" y="213">{points[0].period.slice(0, 7)}</text><text
      x="550"
      y="213">{points.at(-1)?.period.slice(0, 7)}</text
    >
  </svg>
  <figcaption class="chart-caption">
    縦軸は変化を見やすくするため最小値〜最大値を表示。ゼロ始まりではありません。国勢調査による基準の切り替えを含む場合があります。
  </figcaption>
</figure>

---
import { reportUrl } from "../../../../../packages/core/corrections";
import SourceLink from "../../components/SourceLink.astro";
import Layout from "../../layouts/Layout.astro";
import Trend from "../../components/Trend.astro";
import {
  allIssues,
  editorialVerification,
  issueEvidence,
  editorialSources,
} from "../../../../../packages/core/issues";
import { data, fact, compare, wards, number } from "../../data";
export function getStaticPaths() {
  return allIssues.map((issue) => ({
    params: { slug: issue.slug },
    props: { issue },
  }));
}
const { issue } = Astro.props;
const city = fact(data, "141003", issue.metric);
const ranked = compare(data, issue.metric, city.observation.period);
const checkedClaims = issueEvidence(issue.slug).filter(
  (c) => c.kind !== "non_assertion",
);
---

<Layout title={issue.title}
  ><article class="container narrow section prose">
    <p class="breadcrumb">
      <a href="/">ホーム</a> / <a href="/issues/">暮らしの問い</a> / {
        issue.category
      }
    </p><p class="eyebrow">{issue.category}</p><h1 class="page-title">
      {issue.title}
    </h1><p class="lede">{issue.summary}</p><p class="small muted">
      統計の時点：{city.observation.period}
    </p>
    <div class="reading-toggle" aria-label="読む詳しさ">
      <button
        id="brief"
        type="button"
        aria-pressed="true"
        aria-controls="reading-details">まず要点</button
      ><button
        id="full"
        type="button"
        aria-pressed="false"
        aria-controls="reading-details">詳しく読む</button
      >
    </div>

    <h2>{issue.question}</h2><ul class="fact-list">
      <li data-claim-id={city.observation.id}>
        <span class="fact-type">事実</span>{city.statement}<SourceLink
          href={city.source.sourcePage}
        />
        <a
          class="small"
          href={reportUrl(
            Astro.url.pathname,
            city.source.sha256,
            city.observation.id,
          )}>この数字の誤りを報告</a
        >
      </li><li>
        <span class="fact-type analysis">読み方・限界</span>{issue.limits}
      </li>
    </ul>
    <p class="note"><strong>まだ分からないこと</strong><br />{issue.next}</p><a
      class="action"
      href={`/wards/?metric=${issue.metric}`}>自分の区と比べる →</a
    >
    <details class="note" data-testid="claim-evidence">
      <summary>出典・確認状況</summary>
      <p class="small muted" data-testid="editorial-verification">
        見出し・要約・問い・限界・未収録事項の出典照合：{
          editorialVerification.humanReviewed
            ? "人間による確認"
            : "AIによる検証・反証確認"
        }（{
          new Date(editorialVerification.reviewedAt).toLocaleDateString(
            "ja-JP",
            {
              timeZone: "Asia/Tokyo",
            },
          )
        }）。{
          !editorialVerification.humanReviewed && "人間による確認は未実施です。"
        }
      </p>
      <p>
        根拠資料と説明の対応を確認しています。AIの判断に誤りが残る可能性があり、政策効果を保証するものではありません。
      </p>
      {
        checkedClaims.map((c) => (
          <section id={`claim-${c.id.replaceAll("/", "-")}`}>
            <>
              <p>{c.quote}</p>
              <p class="small">
                <a
                  href={reportUrl(
                    Astro.url.pathname,
                    editorialVerification.packetHash,
                    `${c.id}: ${c.quote}`,
                  )}
                >
                  この説明の誤りを報告
                </a>
              </p>
              <ul>
                {c.verification?.evidence.map((e) => {
                  const source = editorialSources.find(
                    (s) => s.id === e.sourceId,
                  );
                  return (
                    <li>
                      <a href={source?.url}>{source?.title}</a>
                      <details>
                        <summary>引用箇所</summary>
                        <pre style="white-space:pre-wrap;overflow-wrap:anywhere">
                          {e.quote}
                        </pre>
                      </details>
                    </li>
                  );
                })}
              </ul>
            </>
          </section>
        ))
      }
    </details>
    <div id="reading-details" class="details-content">
      <h2>横浜市全体の推移</h2><Trend
        geography="141003"
        metric={issue.metric}
      /><h2>18区を同じ時点で比べる</h2><div class="table-wrap">
        <table>
          <caption
            >{city.observation.period}時点・{city.definition.name}（{
              city.definition.unit
            }）</caption
          ><thead
            ><tr
              ><th scope="col">区</th><th scope="col" class="numeric"
                >{city.definition.name}</th
              ><th scope="col">根拠</th></tr
            ></thead
          ><tbody
            >{
              ranked.map((o) => {
                const w = wards.find((w) => w.code === o.geography)!;
                return (
                  <tr>
                    <>
                      <th scope="row">
                        <a href={`/wards/${w.slug}/`}>{w.name}</a>
                      </th>
                      <td class="numeric">{number(o.value)}</td>
                      <td>
                        <SourceLink
                          href={
                            data.snapshots.find((s) => s.id === o.sourceId)!
                              .sourcePage
                          }
                        />
                      </td>
                    </>
                  </tr>
                );
              })
            }</tbody
          >
        </table>
      </div><h2>この数字の定義</h2><p>{city.definition.definition}</p><p>
        資料：横浜市「{city.source.title}」。取得日：{
          city.source.retrievedAt.slice(0, 10)
        }。原本の数値・男女計・市と区の合計をプログラムで検査しています。解釈や因果関係の正しさを保証する検査ではありません。
      </p><h2>政策を考える前に</h2><p>
        このページは統計の読み方を紹介しています。個別政策の効果・費用・優劣は評価していません。政策を比較するには、対象者、期間、費用、成果の定義をそろえた別の検証が必要です。
      </p>
    </div>
    <h2>根拠を自分で確かめる</h2><p>
      <a href={`/sources/#s-${city.source.id}`}
        >原本CSV・取得情報・指標の定義を開く →</a
      >
    </p><p class="small">
      <a href={reportUrl(Astro.url.pathname, editorialVerification.packetHash)}
        >数字や説明の誤りを知らせる</a
      >
    </p>
  </article><script>
    const details = document.querySelector<HTMLElement>("#reading-details");
    const brief = document.querySelector<HTMLButtonElement>("#brief");
    const full = document.querySelector<HTMLButtonElement>("#full");
    function setReading(expanded: boolean) {
      if (!details || !brief || !full) return;
      details.hidden = !expanded;
      brief.setAttribute("aria-pressed", String(!expanded));
      full.setAttribute("aria-pressed", String(expanded));
    }
    brief?.addEventListener("click", () => setReading(false));
    full?.addEventListener("click", () => setReading(true));
    setReading(false);
  </script></Layout
>
